#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>

pthread_spinlock_t spinlock;
int shared_resource = 0;

// Thread 1: Acquires and holds the lock
void* thread_func_1(void* arg) {
    printf("T1: Attempting to lock standard way (blocking)...
");
    if (pthread_spin_lock(&spinlock) == 0) {
        printf("T1: Lock acquired. Holding for 2 seconds.
");
        shared_resource = 10;
        sleep(2);
        printf("T1: Releasing lock.
");
        pthread_spin_unlock(&spinlock);
    } else {
        perror("T1 lock failed");
    }
    return NULL;
}

// Thread 2: Attempts to acquire the lock using trylock
void* thread_func_2(void* arg) {
    sleep(1); // Wait for T1 to acquire the lock first

    printf("T2: Attempting trylock (non-blocking)...
");
    int ret = pthread_spin_trylock(&spinlock);

    if (ret == 0) {
        printf("T2: SUCCESS! Lock acquired. Shared resource value: %d\n", shared_resource);
        pthread_spin_unlock(&spinlock);
    } else if (ret == EBUSY) {
        printf("T2: EBUSY received. Lock is held by T1. T2 continues non-critical work.\n");
    } else {
        fprintf(stderr, "T2: Critical error %d during trylock.\n", ret);
    }
    return NULL;
}

int main() {
    pthread_t t1, t2;

    // Initialize the spin lock (PTHREAD_PROCESS_PRIVATE scope)
    if (pthread_spin_init(&spinlock, PTHREAD_PROCESS_PRIVATE) != 0) {
        perror("pthread_spin_init");
        return 1;
    }

    // Create and join threads
    if (pthread_create(&t1, NULL, thread_func_1, NULL) != 0) { return 1; }
    if (pthread_create(&t2, NULL, thread_func_2, NULL) != 0) { return 1; }

    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    // Destroy the lock
    pthread_spin_destroy(&spinlock);

    return 0;
}
